```tsx
"use client"

import { useId, useState } from "react"
import type { FormEvent } from "react"
import { toast } from "sonner"
import {
  AnnoyedIcon,
  FrownIcon,
  LaughIcon,
  MehIcon,
  MessageSquarePlusIcon,
  SmileIcon,
  type LucideIcon,
} from "lucide-react"

import { Button } from "@/components/ui/button"
import {
  Dialog,
  DialogClose,
  DialogContent,
  DialogDescription,
  DialogFooter,
  DialogHeader,
  DialogTitle,
  DialogTrigger,
} from "@/components/ui/dialog"
import { Label } from "@/components/ui/label"
import { Textarea } from "@/components/ui/textarea"
import { ToggleGroup, ToggleGroupItem } from "@/components/ui/toggle-group"
import {
  Card,
  CardContent,
  CardDescription,
  CardHeader,
  CardTitle,
} from "@/components/ui/card"
import { Badge } from "@/components/ui/badge"

type Rating = {
  value: string
  label: string
  icon: LucideIcon
  prompt: string
}

const RATINGS: Rating[] = [
  {
    value: "1",
    label: "Very unhappy",
    icon: AnnoyedIcon,
    prompt: "What went wrong?",
  },
  {
    value: "2",
    label: "Unhappy",
    icon: FrownIcon,
    prompt: "What could we do better?",
  },
  {
    value: "3",
    label: "Okay",
    icon: MehIcon,
    prompt: "What would make it great?",
  },
  {
    value: "4",
    label: "Happy",
    icon: SmileIcon,
    prompt: "What did you like most?",
  },
  {
    value: "5",
    label: "Delighted",
    icon: LaughIcon,
    prompt: "What did you love?",
  },
]

const MAX_LENGTH = 500

const RECENT_RELEASES = [
  {
    title: "Shared dashboards",
    date: "Mar 12",
    body: "Invite teammates to view and comment on any dashboard without needing a seat.",
  },
  {
    title: "Faster CSV exports",
    date: "Feb 27",
    body: "Exports of up to 1M rows now finish in under 20 seconds and run in the background.",
  },
  {
    title: "Scheduled digests",
    date: "Feb 05",
    body: "Get a weekly summary of your key metrics delivered every Monday morning.",
  },
]

export default function Page() {
  const [open, setOpen] = useState(false)
  const [rating, setRating] = useState("")
  const [message, setMessage] = useState("")
  const [showError, setShowError] = useState(false)

  const ratingLabelId = useId()
  const messageId = useId()
  const errorId = useId()
  const countId = useId()

  const selected = RATINGS.find((r) => r.value === rating)

  function resetForm() {
    setRating("")
    setMessage("")
    setShowError(false)
  }

  function handleOpenChange(next: boolean) {
    setOpen(next)
    if (!next) setShowError(false)
  }

  function handleSubmit(event: FormEvent<HTMLFormElement>) {
    event.preventDefault()
    if (!selected) {
      setShowError(true)
      return
    }
    const trimmed = message.trim()
    toast.success("Thanks for your feedback!", {
      description: trimmed
        ? `You rated us "${selected.label}". We read every message.`
        : `You rated us "${selected.label}". We appreciate you taking the time.`,
    })
    setOpen(false)
    resetForm()
  }

  return (
